function buildLocalTimeDoc() {
  const d = new Date();
  const h = String(d.getHours()).padStart(2, "0");
  const m = String(d.getMinutes()).padStart(2, "0");
  const s = String(d.getSeconds()).padStart(2, "0");
  const h12n = d.getHours() % 12 || 12;
  const h12 = String(h12n).padStart(2, "0");
  const ap = d.getHours() >= 12 ? "PM" : "AM";
  return {
    time: `${h}:${m}:${s}`,
    time_24: `${h}:${m}:${s}`,
    time_12: `${h12}:${m}:${s} ${ap}`,
    date: `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`,
    iso_local: `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}T${h}:${m}`,
    hour: d.getHours(),
    minute: d.getMinutes(),
    second: d.getSeconds(),
    millis: d.getMilliseconds(),
    tz: runtimeContext["geo.tz"]
  };
}

function buildResolvedData(dslDoc, payload) {
  const values = {};
  const numerics = {};
  const series = {};
  const fields = (((dslDoc || {}).data || {}).fields) || {};
  const lookups = (((dslDoc || {}).data || {}).lookups) || {};
  const source = (((dslDoc || {}).data || {}).source) || "http";
  const dataDoc = source === "local_time" ? buildLocalTimeDoc() : (payload || {});

  for (const [key, spec] of Object.entries(fields)) {
    let path;
    let fmt;
    if (typeof spec === "string") {
      path = bindTemplate(spec, values);
      fmt = null;
    } else if (spec && typeof spec === "object") {
      path = bindTemplate(String(spec.path || ""), values);
      fmt = spec.format || null;
      if (fmt && typeof fmt === "object") {
        const lookupName = String(fmt.map_lookup || fmt.mapLookup || "").trim();
        if (lookupName) {
          const lookupMap = lookups[lookupName];
          if (lookupMap && typeof lookupMap === "object") {
            const localMap = (fmt.map && typeof fmt.map === "object") ? fmt.map : {};
            fmt = { ...fmt, map: { ...lookupMap, ...localMap } };
          }
        }
      }
    } else {
      continue;
    }

    const raw = resolvePath(dataDoc, path);
    if (raw === undefined) {
      values[key] = "";
      continue;
    }

    if (Array.isArray(raw)) {
      const nums = raw.map(v => (typeof v === "number" ? v : Number(v))).filter(Number.isFinite);
      series[key] = nums;
      if (nums.length > 0) {
        values[key] = applyFormat(nums[nums.length - 1], fmt || {}, values);
        numerics[key] = nums[nums.length - 1];
      } else {
        values[key] = "";
      }
      continue;
    }

    values[key] = fmt ? applyFormat(raw, fmt, values) : String(raw);
    const n = parseNumberMaybe(raw);
    if (n != null) numerics[key] = n;
  }

  return { values, numerics, series, dataDoc };
}

